#!/usr/bin/env python3
"""Generate the demo sphere mesh.

Kept in the repository so samples/demo/assets/models/sphere.obj can be
regenerated deterministically instead of being hand edited.

Usage:
    python3 tools/scripts/make_sphere.py samples/demo/assets/models/sphere.obj
"""

from __future__ import annotations

import math
import sys
from pathlib import Path

RADIUS = 0.5
RINGS = 8
SEGMENTS = 12


def build() -> str:
    lines = [
        "# Zypher demo sphere (radius 0.5, low poly, generated by tools/scripts/make_sphere.py)",
        "o Sphere",
    ]

    vertices: list[tuple[float, float, float]] = [(0.0, RADIUS, 0.0)]
    for ring in range(1, RINGS):
        phi = math.pi * ring / RINGS
        y = RADIUS * math.cos(phi)
        radius = RADIUS * math.sin(phi)
        for segment in range(SEGMENTS):
            theta = 2.0 * math.pi * segment / SEGMENTS
            vertices.append((radius * math.cos(theta), y, radius * math.sin(theta)))
    vertices.append((0.0, -RADIUS, 0.0))

    for x, y, z in vertices:
        lines.append(f"v {x:.6f} {y:.6f} {z:.6f}")
    for x, y, z in vertices:
        length = math.sqrt(x * x + y * y + z * z)
        lines.append(f"vn {x / length:.6f} {y / length:.6f} {z / length:.6f}")

    texcoords: list[tuple[float, float]] = [(0.5, 1.0)]
    for ring in range(1, RINGS):
        v = 1.0 - ring / RINGS
        for segment in range(SEGMENTS + 1):
            texcoords.append((segment / SEGMENTS, v))
    texcoords.append((0.5, 0.0))
    for u, v in texcoords:
        lines.append(f"vt {u:.6f} {v:.6f}")

    def position_index(ring: int, segment: int) -> int:
        if ring == 0:
            return 1
        if ring == RINGS:
            return len(vertices)
        return 2 + (ring - 1) * SEGMENTS + (segment % SEGMENTS)

    def texcoord_index(ring: int, segment: int) -> int:
        if ring == 0:
            return 1
        if ring == RINGS:
            return len(texcoords)
        return 2 + (ring - 1) * (SEGMENTS + 1) + segment

    for ring in range(RINGS):
        for segment in range(SEGMENTS):
            a = position_index(ring, segment)
            b = position_index(ring, segment + 1)
            c = position_index(ring + 1, segment + 1)
            d = position_index(ring + 1, segment)
            ta = texcoord_index(ring, segment)
            tb = texcoord_index(ring, segment + 1)
            tc = texcoord_index(ring + 1, segment + 1)
            td = texcoord_index(ring + 1, segment)
            if ring != 0:
                lines.append(f"f {a}/{ta}/{a} {b}/{tb}/{b} {c}/{tc}/{c}")
            if ring != RINGS - 1:
                lines.append(f"f {a}/{ta}/{a} {c}/{tc}/{c} {d}/{td}/{d}")

    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    destination = Path(argv[1]) if len(argv) > 1 else Path("samples/demo/assets/models/sphere.obj")
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(build(), encoding="utf-8")
    print(f"wrote {destination}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
